 if(path.startsWith('/engineering/paper-bridge/')||path.startsWith('/literacy/story-map/')||path.startsWith('/nature/sound-map/')||path.startsWith('/nature/leaf-rubbing/')||path.startsWith('/art/paper-shape-collage/')||path.startsWith('/science/weather-journal/')||path.startsWith('/art/mixing-colours/')||path.startsWith('/maths/make-a-pattern/')||path.startsWith('/science/shadow-detectives/'))html=html.replace('<body>','<body class="weather-page">');
