function cards(items){return `<div class="activity-grid">${items.map(a=>`<article class="activity-card" data-subject="${a.subject}" data-ages="${a.ages.join(' ')}" data-search="${e([a.title,a.description,a.tags,subjectLabel(a.subject),a.materials.join(' ')].join(' ').toLowerCase())}"><a href="${url(a)}"><div class="card-image"><img src="/assets/${a.art}.svg" alt="${e(a.alt)}" width="800" height="600" loading="lazy"><h3 class="image-title">${e(a.title)}</h3></div><div class="card-copy"><div class="card-meta"><span>Ages ${a.ageLabel}</span><span>${e(a.time)}</span></div><p>${e(a.description)}</p></div></a></article>`).join('')}</div>`;}
const subjectsGrid=()=>`<div class="subject-grid">${subjects.map(([id,name,desc,art],i)=>`<a class="subject-card ${id}" href="/${id}/"><span class="eyebrow">0${i+1} / EXPLORE</span><h3>${name}</h3><p>${desc}</p><span class="subject-end">${activities.filter(a=>a.subject===id).length} ${activities.filter(a=>a.subject===id).length===1?'activity':'activities'} <span aria-hidden="true">↗</span></span></a>`).join('')}</div>`;
const agesGrid=()=>`<div class="age-grid">${ageGroups.map(([slug,range,name,desc])=>`<a href="/ages/${slug}/"><span class="age-number">${range}<small>years</small></span><span><strong>${name}</strong><small>${desc}</small></span><span aria-hidden="true">↗</span></a>`).join('')}</div>`;
const crumb=(parts)=>`<nav class="breadcrumbs wrap" aria-label="Breadcrumb"><a href="/">Home</a>${parts.map(([label,href])=>`<span aria-hidden="true">/</span>${href?`<a href="${href}">${e(label)}</a>`:`<span aria-current="page">${e(label)}</span>`}`).join('')}</nav>`;
const heading=(eyebrow,title,desc)=>`<div class="page-heading wrap"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${desc}</p></div>`;
page('/','Their first school starts with you','A guided learning journey from baby’s first look onward, with age-guided classes, playful activities and practical support for parents. Free, no sign-up.',`
<section class="hero wrap"><div class="hero-copy"><span class="tape-label">WELCOME TO KIDDO.SCHOOL</span><h1>Their first school<br><em>starts with you.</em></h1><p>A learning journey from baby’s first look onward — simple classes, playful activities and gentle guidance for parents along the way.</p><p class="hero-description">Kiddo.school is a digital school for little kids: age-guided classes from birth, hands-on classrooms as they grow, and short parent-led sessions that fit real life. No sign-up, no pressure — age ranges are a guide, not a test.</p><div class="hero-actions"><a class="button" href="/newborn/0-6-weeks/high-contrast-cards/">Start Today’s Class <span aria-hidden="true">↗</span></a><a class="button button-ghost" href="/learning-path/">Explore the Learning Path <span aria-hidden="true">↗</span></a></div><span class="hero-footnote">Two-to-five-minute classes. Made for everyday moments at home.</span></div><div class="scrapbook" aria-label="A peek at our school"><figure class="hero-paper main-paper"><img src="${newbornBase}newborn-high-contrast-face.webp" width="1080" height="1350" alt="Black and white high-contrast smiling face card for newborns, from the Kiddo.school Newborn 1 class" fetchpriority="high"><figcaption>Class 1: High-contrast cards, from birth.</figcaption></figure><figure class="hero-paper small-paper"><img src="/assets/collage.svg" width="800" height="600" alt="A house and tree made from colourful paper shapes." loading="lazy"><figcaption>Classrooms for bigger kids, too.</figcaption></figure><div class="scribble" aria-hidden="true">a little wonder<br>goes a long way<svg viewBox="0 0 150 70"><path d="M5 10Q80 80 133 17m-3 1-1 22m4-22-23 2" fill="none" stroke="currentColor" stroke-width="2"/></svg></div><div class="round-stamp" aria-hidden="true">FROM FIRST LOOK<br><strong>to big<br>ideas.</strong></div></div></section>
<div class="promise-strip"><div class="wrap"><span>Starts from birth</span><span>Parent-led classes</span><span>Learning that continues off screen</span></div></div>
<section class="section wrap" id="learning-path"><div class="section-heading"><div><span class="eyebrow">THE LEARNING PATH</span><h2>From first look to big ideas.</h2></div><a class="text-link" href="/learning-path/">Open the Learning Path <span aria-hidden="true">↗</span></a></div><p class="lesson-lede">Nine classes are ready now, from birth to age two — each one a short, parent-led session with everything you need on the page. Follow the path in order, or jump straight to your child’s stage. <strong>Age ranges are a guide, not a test. Children learn at their own pace.</strong></p><div class="lp-stages">${stages.map(s=>`<a class="lp-stage" href="${s.href}"><span class="fc-age">${s.name}</span><span class="lp-range">${s.age}</span><span class="lp-open" aria-hidden="true">↗</span></a>`).join('')}</div><div class="lesson-start"><a class="button" href="/newborn/0-6-weeks/high-contrast-cards/">Start Today’s Class <span aria-hidden="true">↗</span></a><span class="lesson-start-hint">Class 1: High-Contrast Cards — the very first class, from birth.</span></div></section>
<section class="section wrap"><div class="notebook"><span class="eyebrow">HOW SCHOOL WORKS</span><h2>Little classes. Real life. Together.</h2><div class="steps-grid"><div><span>01</span><h3>Learn</h3><p>A short class on screen: a few cards, one idea, your voice doing the teaching.</p></div><div><span>02</span><h3>Play</h3><p>Toddlers tap, find and match. Wrong taps are welcome — there are no scores here.</p></div><div><span>03</span><h3>Explore</h3><p>Follow what catches their eye. There is no finish line to reach.</p></div><div><span>04</span><h3>Take it off screen</h3><p>Every class ends in real life: hunt for red, spot a circle, name it together.</p></div><div><span>05</span><h3>Continue tomorrow</h3><p>A new little class whenever it suits you. Short and often wins.</p></div></div></div></section>
${writingSection}<section class="section subject-section" id="subjects"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">OUR LITTLE CLASSROOMS</span><h2>Pick your next adventure.</h2></div><a class="text-link" href="/subjects/">All subjects <span aria-hidden="true">↗</span></a></div>${subjectsGrid()}</div></section>
<section class="section wrap"><div class="section-heading"><div><span class="eyebrow">FROM THE ACTIVITY WALL</span><h2>Ready, set, create!</h2></div><a class="text-link" href="/activities/">All ${activities.length} activities <span aria-hidden="true">↗</span></a></div>${cards(activities.slice(0,3))}</section>
<section class="section wrap" id="ages"><div class="age-panel"><span class="eyebrow">GROW AT YOUR OWN PACE</span><h2>Big fun for every little stage.</h2><p>Ages are a starting point, not a rule. Follow your child's interests and offer the help they need.</p>${agesGrid()}</div></section>
<section class="section wrap"><div class="parents-principal"><div class="tc-note-block tc-parents"><span class="eyebrow">FOR PARENTS</span><h2>You are the teacher.<br>We are the helper.</h2><p>Every class is led by you, in your own words, at your child’s pace. The grown-ups’ guide covers supervision, adaptations and printing — no teaching experience needed.</p><a class="text-link" href="/grown-ups/">Visit the grown-ups’ guide <span aria-hidden="true">↗</span></a></div><div class="tc-note-block tc-principal"><span class="eyebrow">FROM THE PRINCIPAL’S OFFICE</span><h2>A short note home.</h2><p class="tc-say">“Five playful minutes together can be enough. Continue the lesson naturally during your day — name the colors you see, count the stairs, wonder about the weather.”</p><p class="tc-who">— The Principal, Kiddo.school</p><a class="text-link" href="/about/#principal">More from the Principal’s Office <span aria-hidden="true">↗</span></a></div></div></section>
<section class="section wrap"><div class="feature"><img src="/assets/bridge.svg" width="800" height="600" alt="A folded paper bridge supporting a wooden block." loading="lazy"><div><span class="tape-label">A QUESTION WORTH TRYING</span><h2>How strong can<br>a piece of paper be?</h2><p>A couple of folds can change everything. Build a bridge, test your idea, and see what happens next.</p><a class="button" href="/engineering/paper-bridge/">Let's find out <span aria-hidden="true">↗</span></a></div></div></section>
<section class="section wrap"><div class="final-cta"><span class="eyebrow">START WHERE YOU ARE</span><h2>Ready for today’s class?</h2><p>Two to five playful minutes, wherever you are — today’s class is one tap away.</p><div class="hero-actions"><a class="button" href="/newborn/0-6-weeks/high-contrast-cards/">Start Today’s Class <span aria-hidden="true">↗</span></a><a class="button button-ghost" href="/learning-path/">Explore the Learning Path <span aria-hidden="true">↗</span></a></div></div></section>`);
page('/subjects/','Explore activities by subject','Six hands-on subjects for curious children: art, science, nature, maths, literacy and engineering.',crumb([['Subjects']])+heading('SIX WAYS TO WONDER','Find your little classroom.','Start with something you love, or try something completely new.')+`<section class="wrap section compact">${subjectsGrid()}</section>`);
page('/ages/','Activities by age','Find hands-on activities for ages 3–5, 6–8 and 9–12, with adaptations for younger and older learners.',crumb([['By age']])+heading('AT YOUR OWN PACE','An idea for every stage.','Age guides help you begin. Each activity includes ways to make it simpler or take it further.')+`<section class="wrap section compact"><div class="age-panel">${agesGrid()}</div></section>`);
for(const [id,name,desc] of subjects)page(`/${id}/`,`${name}: hands-on activities`,`${desc} Explore ${name.toLowerCase()} activities with materials, clear steps and age adaptations.`,crumb([['Subjects','/subjects/'],[name]])+heading('OUR LITTLE CLASSROOMS',name,desc)+`<section class="wrap section compact">${cards(activities.filter(a=>a.subject===id))}${id==='literacy'?"<div class=\"handwriting-cta\"><div><h2>Write, trace & draw on screen.</h2><p>A space to practise letters, numbers and your name with a finger, stylus or mouse.</p></div><a class=\"button\" href=\"/literacy/handwriting-practice/\">Try handwriting \u2197</a></div>":''}<p class="collection-note">Explore our ${name.toLowerCase()} activities together. <a href="/activities/">Explore the full collection.</a></p></section>`);
for(const [slug,range,name,desc] of ageGroups)page(`/ages/${slug}/`,`Activities for ages ${range}`,`Hands-on activities for children aged ${range}. Explore creative projects with clear instructions and adult guidance.`,crumb([['By age','/ages/'],[`Ages ${range}`]])+heading(`AGES ${range}`,name,`${desc} Choose an activity together and adapt it to your learner.`)+`<section class="wrap section compact">${cards(activities.filter(a=>a.ages.includes(slug)))}</section>`);
function catalogue(search=false){return crumb([[search?'Search':'All activities']])+heading('THE ACTIVITY CUPBOARD',search?'What shall we discover?':'A little idea for today.','Ten free activities. Everyday materials. Plenty of room to make them your own.')+`<section class="wrap section compact" data-catalogue><div class="bean-next"><h2>The Grow a Bean activity collection</h2>${beanLinks()}</div><div class="handwriting-cta"><div><h2>Write, trace & draw on screen.</h2><p>A space to practise letters, numbers and your name with a finger, stylus or mouse.</p></div><a class="button" href="/literacy/handwriting-practice/">Try handwriting ↗</a></div><form class="filters" role="search"><div class="search-field"><label for="query">Search activities</label><div>${svgSearch}<input id="query" name="q" type="search" placeholder="Try plants, paper, patterns…" autocomplete="off"></div></div><div><label for="subject">Subject</label><select id="subject" name="subject"><option value="">All subjects</option>${subjects.map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></div><div><label for="age">Age</label><select id="age" name="age"><option value="">All ages</option>${ageGroups.map(([slug,range])=>`<option value="${slug}">${range} years</option>`).join('')}</select></div><button class="clear-button" type="reset">Clear filters</button></form><noscript><p class="notice">Search needs JavaScript. All ten activities are listed below; you can also browse <a href="/subjects/">by subject</a> or <a href="/ages/">by age</a>.</p></noscript><p id="result-count" class="result-count" aria-live="polite" aria-atomic="true">10 activities to explore</p>${cards(activities)}<div id="no-results" class="empty-state" hidden><h2>No little adventures found.</h2><p>Try a broader word like “paper”, or clear a filter to see more ideas.</p><button class="button" type="button" data-clear>Show all activities</button></div></section>`;}
