for(const a of activities){
 const schema={'@context':'https://schema.org','@type':'LearningResource',name:a.title,description:a.description,url:site+url(a),image:site+`/assets/${a.art}.svg`,inLanguage:'en',learningResourceType:'Hands-on activity',typicalAgeRange:a.ageLabel.replace('–','-'),isAccessibleForFree:true,educationalUse:'Activity',teaches:a.skills};
 const breadcrumb={'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[['Home','/'],[subjectLabel(a.subject),`/${a.subject}/`],[a.title,url(a)]].map(([name,path],i)=>({'@type':'ListItem',position:i+1,name,item:site+path}))};
 page(url(a),`${a.title}: a hands-on ${a.subject} activity`,`${a.description} For ages ${a.ageLabel}; includes materials, steps and a free printable image sheet.`,crumb([['Subjects','/subjects/'],[subjectLabel(a.subject),`/${a.subject}/`],[a.title]])+`<article><header class="activity-hero wrap"><div><span class="eyebrow">${e(subjectLabel(a.subject))} / MAKE · LEARN · DISCOVER</span><h1>${e(a.title)}<span class="title-dot">.</span></h1><p class="activity-subtitle">${e(a.subtitle)}</p><div class="activity-tags"><span>Ages ${a.ageLabel}</span><span>${e(a.time)}</span><span>${e(a.place)}</span></div><p>${e(a.intro)}</p><div class="button-row"><a class="button" href="#instructions">Let's get started <span aria-hidden="true">↓</span></a><a class="text-link" href="#download">Get the activity sheet</a></div></div><figure class="activity-photo"><img src="/assets/${a.art}.svg" width="800" height="600" alt="${e(a.alt)}"><figcaption>${e(a.skills)}</figcaption></figure></header>${a.slug==='grow-a-bean'?'<section class="wrap"><h2>Seven little investigations.</h2><p>Draw, type and save your work on separate activity pages.</p>'+beanLinks()+'</section>':a.slug==='sink-or-float'?'<section class="wrap"><h2>Choose your next experiment activity.</h2>'+sinkLinks()+'</section>':a.slug==='weather-journal'?'<section class="wrap"><h2>Choose a weather activity.</h2>'+weatherLinks()+'</section>':a.slug==='paper-bridge'?'<section class="wrap"><h2>Choose a bridge activity.</h2>'+bridgeLinks()+'</section>':a.slug==='story-map'?'<section class="wrap"><h2>Choose a storytelling activity.</h2>'+storyLinks()+'</section>':a.slug==='sound-map'?'<section class="wrap"><h2>Choose a listening activity.</h2>'+soundLinks()+'</section>':a.slug==='paper-shape-collage'?'<section class="wrap"><h2>Choose a shape activity.</h2>'+shapeLinks()+'</section>':a.slug==='mixing-colours'?'<section class="wrap"><h2>Choose a colour activity.</h2>'+colourLinks()+'</section>':a.slug==='make-a-pattern'?'<section class="wrap"><h2>Five little pattern activities.</h2><p>Draw, type and save your work on separate activity pages.</p>'+patternLinks()+'</section>':a.slug==='leaf-rubbing'?'<section class="wrap"><h2>Five little leaf activities.</h2><p>Draw, type and save your work on separate activity pages.</p>'+leafLinks()+'</section>':a.slug==='shadow-detectives'?'<section class="wrap"><h2>Five little shadow activities.</h2><p>Draw, type and save your work on separate activity pages.</p>'+shadowLinks()+'</section>':''}<div class="activity-layout wrap"><aside class="supplies"><span class="eyebrow">BEFORE YOU BEGIN</span><h2>Gather your bits.</h2><p class="small">Tick things off as you get ready.</p><ul class="checklist">${a.materials.map((m,i)=>`<li><label><input type="checkbox"><span>${e(m)}</span></label></li>`).join('')}</ul><div class="safety"><h3>A note for grown-ups</h3><p>${e(a.safety)}</p></div><a class="text-link" href="/grown-ups/">A little more guidance ↗</a></aside><div class="instructions"><section id="instructions"><span class="eyebrow">ONE STEP AT A TIME</span><h2>Let's make it happen.</h2><ol class="instruction-list">${a.steps.map(([title,text])=>`<li><h3>${e(title)}</h3><p>${e(text)}</p></li>`).join('')}</ol></section><section class="learning-note"><span class="eyebrow">THE LITTLE BIT OF LEARNING</span><h2>What's happening here?</h2><p>${e(a.why)}</p></section><section><h2>Keep the wondering going.</h2><ul class="questions">${a.questions.map(q=>`<li>${e(q)}</li>`).join('')}</ul></section><section><h2>Make it work for you.</h2><div class="adaptations"><div><h3>Keep it simple</h3><p>${e(a.younger)}</p></div><div><h3>Take it further</h3><p>${e(a.older)}</p></div></div><details><summary>Not quite going to plan?</summary><p>${e(a.troubleshoot)}</p></details></section><section class="download-note" id="download"><div><span class="eyebrow">A PLACE FOR YOUR IDEAS</span><h2>${e(a.sheet)}</h2><p>${e(a.sheetPrompt)}</p><p class="small">Free image · prints on A4 or Letter using “fit to page”. Plain paper works just as well.</p><a class="button" href="/downloads/${a.slug}.svg" download="${a.slug}-kiddo-school.svg">Download the sheet <span aria-hidden="true">↓</span></a><a class="text-link sheet-preview" href="/downloads/${a.slug}.svg">Open image to print ↗</a></div><img src="/downloads/${a.slug}.svg" width="1600" height="2200" alt="Preview of the ${e(a.sheet.toLowerCase())} drawing sheet" loading="lazy"></section><p class="small usage-note">You may print and use this original activity sheet at home or in your classroom. Please link to the activity page when sharing it online.</p></div></div></article><section class="section wrap"><div class="section-heading"><div><span class="eyebrow">ONE IDEA LEADS TO ANOTHER</span><h2>Keep exploring.</h2></div><a class="text-link" href="/activities/">All activities ↗</a></div>${cards(activities.filter(b=>b!==a&&b.ages.some(age=>a.ages.includes(age))).slice(0,3))}</section>`,{image:a.art,schema:[schema,breadcrumb]});
}
const prose=(title,desc,content)=>crumb([[title]])+heading('KIDDO.SCHOOL',title,desc)+`<div class="prose wrap">${content}</div>`;
page('/grown-ups/','For parents and teachers','Simple guidance for using Kiddo.school activities at home and in the classroom, including supervision, adaptations and printing.',prose('A little help for grown-ups.','You do not need a perfect setup. Just a little time, a few materials and room for questions.',`<h2>Start with the child in front of you</h2><p>The age labels are guides, not tests or promises. Read the instructions first and decide whether the materials and steps suit your child. Offer more help, skip a step or let an idea grow in a different direction.</p><h2>Stay nearby</h2><p>An adult should choose a suitable place and supervise activities. Follow the specific safety note on each page, keep small items away from younger children, and help with tools. Never eat experiment materials.</p><h2>Use what you have</h2><p>Most activities use paper, crayons and everyday materials. The full list is on each page. A download is optional: a blank sheet of paper is enough to begin.</p><h2>Print an activity sheet</h2><p>Use “Open image to print” on an activity page, then your browser's Print command. Choose A4 or Letter paper, portrait orientation and fit to page. The SVG stays sharp when enlarged. If your printing app cannot open SVG files, print from a browser instead.</p><h2>Make space for different ways of learning</h2><p>Children can point, speak, draw or ask an adult to write. Work in shorter bursts, use larger materials, and offer a quiet space. Each guide includes a simpler version and an extra challenge.</p><h2>In the classroom</h2><p>Read through the guide, prepare materials and adapt for your group. Print the sheets for your own class. These activities support exploration; they are not an accredited curriculum or an assessment of a child's progress.</p>`));
page('/about/','About Kiddo.school','Kiddo.school is a digital school starting from birth: age-guided classes for babies and toddlers, plus hands-on classrooms and activities for older children.',prose('A little school of possibility.','Make · Learn · Discover.',`<h2>Their first school starts with you</h2><p>Kiddo.school is a growing digital school for curious children and the adults learning alongside them. The journey begins at birth with short, parent-led baby and toddler classes, and continues through hands-on classrooms — art, science, nature, maths, stories and engineering — as children grow. Nine classes from birth to age two are ready today, with more on the drawing table.</p><h2>More curiosity, less perfection</h2><p>A crooked collage, a bridge that bends or a seed that has not sprouted can all begin a useful conversation. The aim is to notice, try, question and make something your own.</p><h2 id="principal">From the Principal’s Office</h2><p>Welcome to Kiddo.school. This school is a little different: you are the teacher, and we are the helper. Every class is short enough to fit real life — five playful minutes together can be enough, and you can continue the lesson naturally during your day.</p><p>Two promises from the school office: age ranges here are guides, never tests or developmental deadlines, and nothing on Kiddo School is a score. Children learn at their own pace, and noticing one red thing together already counts as a class.</p><p><a class="button" href="/learning-path/">Explore the Learning Path ↗</a></p><h2>Simple and open to explore</h2><p>The school is free to browse, with no account required. Every class and activity includes parent guidance, age adaptations and clear steps. The collection includes original illustrations, printable image sheets and interactive on-screen classes.</p><p><a class="button" href="/activities/">Find your first activity ↗</a></p>`));
page('/privacy/','Privacy','How this static Kiddo.school pilot handles browsing, search and downloads without accounts or submitted activity data.',prose('Privacy, in plain language.','This pilot keeps things simple.',`<p>Last updated: 4 October 2026.</p><h2>No accounts or submissions</h2><p>This website has no sign-up, comments, upload forms, mailing list or database. It does not ask children to send names, photographs or completed worksheets.</p><h2>Search stays in your browser</h2><p>Search and filters run in your browser. The search text and selected filters may appear in the page URL so you can bookmark a search. A hosting provider may see that URL when the page is loaded, so do not enter personal or sensitive information in search.</p><h2>No site analytics or advertising scripts</h2><p>This pilot does not set application cookies, use browser storage, or include third-party analytics, advertising, tracking pixels or externally hosted fonts. Material checkboxes reset when you leave or reload the page. Handwriting, plant-activity drawings and typed answers stay in temporary browser memory, are never uploaded, and disappear when you refresh or close the page. The Save button creates an image on your device.</p><h2>Hosting and downloads</h2><p>A hosting provider may process ordinary technical information, such as IP addresses and request logs, to serve and protect the website. Downloaded sheets stay on your device; the website does not receive what you write or draw on them.</p><h2>Future changes</h2><p>If forms, analytics, advertising or other services are added, this page should be updated before those features are enabled.</p>`));
page('/404.html','Page not found','This page is not in our activity cupboard. Explore all Kiddo.school activities to find a new idea.',heading('A LITTLE WRONG TURN','This page wandered off.','Let’s find you something to make, learn or discover.')+`<div class="wrap error-actions"><a class="button" href="/activities/">Explore activities ↗</a><a class="text-link" href="/">Back to the homepage</a></div>`,{noindex:true});
page('/literacy/handwriting-practice/','Handwriting practice for kids: trace, write and draw','Free on-screen handwriting practice for children. Trace letters, write numbers or your name with a finger, stylus or mouse, then save your picture.',crumb([['Story Corner','/literacy/'],['Handwriting practice']])+heading('WRITE · TRACE · DRAW','A little practice, at your pace.','Try together with a grown-up. Use the writing space below, or copy the same prompt into a notebook.')+writingSection+`<section class="prose wrap"><h2>Start small.</h2><p>Choose one letter or number and practise for a few minutes. Model it slowly, then invite your child to try. Use Undo freely: this is exploration, not a score or a handwriting assessment.</p><h2>Make it comfortable.</h2><p>Rest the device on a stable surface. A fingertip works; a stylus is optional. Try a thicker line and a larger movement if fine movements are difficult. Paper and crayons are always a good alternative. <a href="/downloads/handwriting-practice.svg" download>Download the printable handwriting sheet.</a></p><h2>Keep what you make.</h2><p>Save your page as a PNG image before closing or refreshing. Nothing you draw is sent to us or stored online. Clear and activity changes can be undone during this visit.</p></section>`,{schema:[{'@context':'https://schema.org','@type':'LearningResource',name:'Handwriting practice',learningResourceType:'Interactive practice',isAccessibleForFree:true,inLanguage:'en'}]});
